// so-context OpenCode plugin — auto-generated by `so-context setup`
//
// Delegates pre-tool routing decisions to the shared Rust hook implementation,
// so OpenCode uses the same reroute and session-injection semantics as
// Codex/Claude instead of maintaining a second copy in TypeScript.
//
// Hooks used:
//   tool.execute.before  — asks `so-context hook pre-tool --host opencode`
//                          whether to inject `_so_session_id`, deny, or pass
//   permission.ask       — blocks native read/search permissions so OpenCode
//                          retries through so-context MCP tools instead
//   session.compacted    — calls `so-context hook post-compact` to reset cache
// __SO_CONTEXT_PERMISSION_BACKUP__=__SO_CONTEXT_PERMISSION_BACKUP_JSON__

import type { Plugin } from "@opencode-ai/plugin";

type HookDecision = {
  permissionDecision?: string;
  permissionDecisionReason?: string;
  updatedInput?: Record<string, unknown>;
};

type HookResult =
  | { kind: "ok"; decision: HookDecision | null }
  | { kind: "error"; message: string };

type PluginShell = any;

const SO_CONTEXT_BINARY = "__SO_CONTEXT_BINARY__";
const SO_CONTEXT_TOOL_PREFIX = "__SO_CONTEXT_TOOL_PREFIX__";
const SESSION_ID_PATHS: string[] = __SO_CONTEXT_SESSION_ID_PATHS__;
const NATIVE_READ_TOOL_NAMES = new Set(__SO_CONTEXT_NATIVE_READ_TOOL_NAMES__);
const NATIVE_SEARCH_TOOL_NAMES = new Set(__SO_CONTEXT_NATIVE_SEARCH_TOOL_NAMES__);
const NATIVE_SHELL_TOOL_NAMES = new Set(__SO_CONTEXT_NATIVE_SHELL_TOOL_NAMES__);
const NATIVE_READ_PERMISSION_TYPES = new Set(["read"]);
const NATIVE_SEARCH_PERMISSION_TYPES = new Set(["grep", "search"]);

function readStringPath(input: unknown, path: string): string | null {
  const value = path.split(".").reduce<unknown>((current, segment) => {
    if (current == null || typeof current !== "object") return undefined;
    return (current as Record<string, unknown>)[segment];
  }, input);

  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function resolveSessionId(input: unknown): string {
  for (const path of SESSION_ID_PATHS) {
    const value = readStringPath(input, path);
    if (value) return value;
  }
  return "";
}

async function runPreToolHook(
  $: PluginShell,
  input: Record<string, unknown>,
  args: Record<string, unknown>,
): Promise<HookResult> {
  const payload = JSON.stringify({
    tool_name: String(input.tool ?? ""),
    tool_input: args,
    session: input.session,
    sessionID: input.sessionID,
  });

  try {
    const stdout = String(
      await ($`echo ${payload} | ${SO_CONTEXT_BINARY} hook pre-tool --host opencode` as any).text(),
    ).trim();
    if (!stdout) return { kind: "ok", decision: null };

    const parsed = JSON.parse(stdout);
    const hookOutput = parsed?.hookSpecificOutput;
    if (!hookOutput || typeof hookOutput !== "object") {
      return { kind: "ok", decision: null };
    }
    return { kind: "ok", decision: hookOutput as HookDecision };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return { kind: "error", message };
  }
}

function shouldDelegateToSharedHook(toolName: string): boolean {
  return (
    toolName.startsWith(SO_CONTEXT_TOOL_PREFIX) ||
    NATIVE_READ_TOOL_NAMES.has(toolName) ||
    NATIVE_SEARCH_TOOL_NAMES.has(toolName) ||
    NATIVE_SHELL_TOOL_NAMES.has(toolName)
  );
}

function replaceOutputArgs(output: { args?: Record<string, unknown> }, updatedInput: Record<string, unknown>): void {
  if (!output.args || typeof output.args !== "object") {
    output.args = { ...updatedInput };
    return;
  }

  for (const key of Object.keys(output.args)) {
    delete output.args[key];
  }
  Object.assign(output.args, updatedInput);
}

function fallbackInjectSessionId(output: { args?: Record<string, unknown> }, sessionId: string): void {
  if (!output.args || typeof output.args !== "object") {
    output.args = { _so_session_id: sessionId };
    return;
  }

  output.args._so_session_id = sessionId;
}

function hookFailureMessage(toolName: string, message: string): string {
  return `[so-context] shared pre-tool hook failed for ${toolName}: ${message}`;
}

function shouldDenyNativePermission(input: { type?: unknown }): boolean {
  const permissionType = String(input.type ?? "").trim().toLowerCase();
  return (
    NATIVE_READ_PERMISSION_TYPES.has(permissionType) ||
    NATIVE_SEARCH_PERMISSION_TYPES.has(permissionType)
  );
}

export const SoContextPlugin: Plugin = async ({ $ }) => {
  return {
    "permission.ask": async (input, output) => {
      if (shouldDenyNativePermission(input as { type?: unknown })) {
        output.status = "deny";
      }
    },

    "tool.execute.before": async (input, output) => {
      const toolName = String(input.tool ?? "");
      if (!shouldDelegateToSharedHook(toolName)) return;
      const isSelfTool = toolName.startsWith(SO_CONTEXT_TOOL_PREFIX);
      const sessionId = isSelfTool ? resolveSessionId(input) : "";

      const hookResult = await runPreToolHook(
        $,
        input as Record<string, unknown>,
        (output.args as any) ?? {},
      );
      if (hookResult.kind === "error") {
        const message = hookFailureMessage(toolName, hookResult.message);
        if (isSelfTool) {
          console.warn(message);
          if (sessionId) fallbackInjectSessionId(output as any, sessionId);
          return;
        }
        throw new Error(`${message}. Native reroute was not bypassed.`);
      }

      const hookOutput = hookResult.decision;
      if (!hookOutput) {
        if (sessionId) fallbackInjectSessionId(output as any, sessionId);
        return;
      }

      if (
        hookOutput.permissionDecision === "allow" &&
        hookOutput.updatedInput &&
        typeof hookOutput.updatedInput === "object"
      ) {
        replaceOutputArgs(output as any, hookOutput.updatedInput);
        return;
      }

      if (hookOutput.permissionDecision === "deny") {
        throw new Error(String(hookOutput.permissionDecisionReason ?? "so-context blocked this tool call"));
      }
    },

    "session.compacted": async (input) => {
      // After compaction the agent's context window is reset. Tell the daemon
      // to clear file-visit cache entries for this session so it delivers full
      // file content again on the next so_read call.
      const sessionId = resolveSessionId(input);
      if (!sessionId) return;

      const payload = JSON.stringify({
        session: { id: sessionId },
        sessionID: sessionId,
      });
      try {
        await $`echo ${payload} | ${SO_CONTEXT_BINARY} hook post-compact --host opencode`.quiet();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.warn(`[so-context] shared post-compact hook failed: ${message}`);
      }
    },
  };
};
